const crypto = require('crypto');
const secret = String($env.N8N_WEBHOOK_SECRET || '');
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n'); }
const item = items[0];
const headers = item.json.headers || {};
const provided = String(headers['x-crm-signature'] || headers['X-CRM-Signature'] || '');
// Raw body requires the CRM Webhook node "Raw Body" option (binary); fall back to canonical JSON.
let raw;
if (item.binary && item.binary.data && item.binary.data.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else {
  raw = JSON.stringify(item.json.body || {});
}
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
const ok = provided.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(provided), Buffer.from(expected));
if (!ok) { throw new Error('Invalid X-CRM-Signature -- webhook rejected'); }
const env = JSON.parse(raw);
// Idempotency: dedupe on the envelope event_id (at-least-once delivery).
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
if (env.event_id && sd.seen[env.event_id]) { return []; }
if (env.event_id) { sd.seen[env.event_id] = Date.now(); }
const data = env.data || {};
if (env.topic !== 'lead.qualified') { return []; }

if (!data.lead_id || !data.assigned_to) { return []; }
return [{ json: { lead_id: data.lead_id, assigned_to: data.assigned_to } }];
